const request=$input.first().json;
const provided=request.headers?.['x-n8n-secret'];
if(!provided||provided!==$env.N8N_SHARED_SECRET) throw new Error('Unauthorized webhook request');
const rawUrl=String(request.query?.url??request.body?.url??'').trim();
const match=rawUrl.match(/^https?:\/\/([^\/?#]+)(?:[\/?#]|$)/i);
if(!match||rawUrl.length>2048) throw new Error('QR URL must be a valid HTTP(S) address');
const domain=match[1].split(':')[0].toLowerCase();
if(!domain||domain.length>253) throw new Error('QR URL hostname is invalid');
return [{json:{url:rawUrl,domain,source:'qr',validated_at:new Date().toISOString()}}];
